// SUPABASE CLIENT
// ═══════════════════════════════════════════════════════════════════════════════
const SUPABASE_URL = "https://ihbzodmssqhrdihnmabo.supabase.co";
const SUPABASE_KEY = "sb_publishable_FU-hM7ZrgT5NyGcxbuoTjg_7l4147gS";

// Minimal Supabase client (CDN olmadan)
const sb = (() => {
  const headers = {
    "apikey": SUPABASE_KEY,
    "Authorization": `Bearer ${SUPABASE_KEY}`,
    "Content-Type": "application/json",
    "Prefer": "return=representation",
  };

  const authHeaders = (token) => token ? {
    ...headers,
    "Authorization": `Bearer ${token}`,
  } : headers;

  let _token = null;
  let _user  = null;

  // ─── AUTH ────────────────────────────────────────────────
  const auth = {
    async signUp(email, password, meta = {}) {
      const r = await fetch(`${SUPABASE_URL}/auth/v1/signup`, {
        method:"POST",
        headers: { ...headers, "Content-Type":"application/json" },
        body: JSON.stringify({ email, password, data: meta }),
      });
      const d = await r.json();
      if(d.access_token) { _token = d.access_token; _user = d.user; }
      return d;
    },
    async signIn(email, password) {
      // Supabase v2 — token endpoint
      const r = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
        method:"POST",
        headers: {
          "apikey": SUPABASE_KEY,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email, password }),
      });
      const d = await r.json();
      if(d.access_token) {
        _token = d.access_token;
        _user  = d.user;
        // Session'ı kaydet
        const session = {
          access_token: d.access_token,
          refresh_token: d.refresh_token,
          user: d.user,
          expires_at: Math.floor(Date.now()/1000) + (d.expires_in || 3600),
        };
        localStorage.setItem('sb_session', JSON.stringify(session));
      }
      return d;
    },
    async signOut() {
      try {
        await fetch(`${SUPABASE_URL}/auth/v1/logout`, {
          method:"POST",
          headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${_token}` },
        });
      } catch(e) {}
      _token = null; _user = null;
      localStorage.removeItem('sb_session');
    },
    setSession(s) {
      _token = s.access_token;
      _user  = s.user;
    },
    clearSession() {
      _token = null; _user = null;
      localStorage.removeItem('sb_session');
    },
  };

  // ─── DATABASE ────────────────────────────────────────────
  const from = (table) => {
    const base = `${SUPABASE_URL}/rest/v1/${table}`;
    const h = () => ({ "apikey": SUPABASE_KEY, "Authorization": `Bearer ${_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=representation" });

    return {
      async select(cols = "*", filters = "") {
        const r = await fetch(`${base}?select=${cols}${filters ? "&" + filters : ""}`, { headers: h() });
        return r.json();
      },
      async insert(data) {
        const r = await fetch(base, {
          method:"POST", headers: h(),
          body: JSON.stringify(data),
        });
        return r.json();
      },
      async update(data, filter) {
        const r = await fetch(`${base}?${filter}`, {
          method:"PATCH", headers: h(),
          body: JSON.stringify(data),
        });
        return r.json();
      },
      async delete(filter) {
        const r = await fetch(`${base}?${filter}`, {
          method:"DELETE", headers: h(),
        });
        return r.ok;
      },
      async upsert(data) {
        const r = await fetch(base, {
          method:"POST",
          headers: { ...h(), "Prefer": "resolution=merge-duplicates,return=representation" },
          body: JSON.stringify(data),
        });
        return r.json();
      },
    };
  };

  // ─── STORAGE ─────────────────────────────────────────────
  const storage = {
    async upload(bucket, path, file, contentType) {
      const h = { ...authHeaders(_token), "Content-Type": contentType || file.type };
      delete h["Content-Type"]; // Let browser set it for FormData
      const r = await fetch(`${SUPABASE_URL}/storage/v1/object/${bucket}/${path}`, {
        method:"POST",
        headers: { ...authHeaders(_token), "Content-Type": contentType || file.type },
        body: file,
      });
      if(!r.ok) return null;
      return `${SUPABASE_URL}/storage/v1/object/public/${bucket}/${path}`;
    },
    async remove(bucket, paths) {
      const r = await fetch(`${SUPABASE_URL}/storage/v1/object/${bucket}`, {
        method:"DELETE",
        headers: authHeaders(_token),
        body: JSON.stringify({ prefixes: paths }),
      });
      return r.ok;
    },
    url(bucket, path) {
      return `${SUPABASE_URL}/storage/v1/object/public/${bucket}/${path}`;
    },
  };

  return { auth, from, storage };
})();

// ─── GÖRSEL SIKIŞTIRMA ───────────────────────────────────────────────────────
async function compressImage(file, maxPx = 400, quality = 0.75, maxKB = 100) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const scale = Math.min(1, maxPx / Math.max(img.width, img.height));
      const w = Math.round(img.width  * scale);
      const h = Math.round(img.height * scale);
      const canvas = document.createElement("canvas");
      canvas.width = w; canvas.height = h;
      canvas.getContext("2d").drawImage(img, 0, 0, w, h);
      canvas.toBlob(
        (blob) => resolve(blob || file),
        "image/jpeg", quality
      );
    };
    img.src = URL.createObjectURL(file);
  });
}

// ─── SUPABASE HOOKS ───────────────────────────────────────────────────────────
function useSupabase() {
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState(null);

  // Ödevleri yükle
  const loadAssignments = async (studentIds) => {
    if(!studentIds?.length) return [];
    const filter = `student_id=in.(${studentIds.join(",")})`;
    const data = await sb.from("assignments").select("*", filter);
    return Array.isArray(data) ? data : [];
  };

  // Öğrencileri yükle
  const loadStudents = async () => {
    try {
      const data = await sb.from("students").select("*");
      return Array.isArray(data) ? data : [];
    } catch(e) {
      return [];
    }
  };

  // Profil yükle
  const loadProfile = async (uid) => {
    const data = await sb.from("profiles").select("*", `id=eq.${uid}`);
    return Array.isArray(data) ? data[0] : null;
  };

  // Ödev kaydet
  const saveAssignment = async (asgn) => {
    setLoading(true);
    const payload = {
      student_id:   asgn.childId,
      title:        asgn.title,
      game:         asgn.game,
      letter:       asgn.letter,
      difficulty:   asgn.difficulty,
      status:       asgn.status || "onay bekliyor",
      approved:     asgn.approved || false,
      due_date:     asgn.dueDate,
      custom_words: asgn.customWords,
    };
    console.log('[saveAssignment] inserting payload:', payload);
    try {
      const result = await sb.from("assignments").insert(payload);
      console.log('[saveAssignment] raw result:', result);
      if(Array.isArray(result) && result[0]?.code) {
        console.error('[saveAssignment] Supabase error:', result[0]);
      }
      return Array.isArray(result) ? result[0] : null;
    } catch(e) {
      console.error('[saveAssignment] caught exception:', e);
      setError(e);
      return null;
    } finally { setLoading(false); }
  };

  // Ödev güncelle
  const updateAssignment = async (id, data) => {
    return sb.from("assignments").update(data, `id=eq.${id}`);
  };

  // Teslim kaydet (fotoğraf/ses)
  const saveSubmission = async (sub) => {
    return sb.from("submissions").insert(sub);
  };

  // Teslim sil
  const deleteSubmission = async (id) => {
    return sb.from("submissions").delete(`id=eq.${id}`);
  };

  // Profil oluştur/güncelle
  const upsertProfile = async (profile) => {
    return sb.from("profiles").upsert(profile);
  };

  // Öğrenci kaydet
  const saveStudent = async (student) => {
    return sb.from("students").insert(student);
  };

  // Seans talepleri
  const loadRequests = async () => {
    const data = await sb.from("session_requests").select("*");
    return Array.isArray(data) ? data : [];
  };

  const saveRequest = async (req) => {
    return sb.from("session_requests").insert(req);
  };

  const updateRequest = async (id, data) => {
    return sb.from("session_requests").update(data, `id=eq.${id}`);
  };

  // Müsait saatler
  const loadAvailability = async () => {
    const data = await sb.from("availability").select("*", "active=eq.true");
    return Array.isArray(data) ? data : [];
  };

  const saveAvailability = async (slot) => {
    return sb.from("availability").insert(slot);
  };

  const deleteAvailability = async (id) => {
    return sb.from("availability").delete(`id=eq.${id}`);
  };

  // Seanslar
  const loadSessions = async () => {
    const data = await sb.from("sessions").select("*");
    return Array.isArray(data) ? data : [];
  };

  const saveSession = async (session) => {
    return sb.from("sessions").insert(session);
  };

  // Avatar yükle (sıkıştırılmış)
  const uploadAvatar = async (file, uid) => {
    const compressed = await compressImage(file, 300, 0.75, 100);
    const path = `${uid}/avatar.jpg`;
    return sb.storage.upload("avatars", path, compressed, "image/jpeg");
  };

  // Teslim fotoğrafı yükle
  const uploadSubmissionPhoto = async (file, assignmentId) => {
    const compressed = await compressImage(file, 800, 0.80, 200);
    const path = `${assignmentId}/${Date.now()}.jpg`;
    return sb.storage.upload("submissions", path, compressed, "image/jpeg");
  };

  return {
    loading, error,
    loadAssignments, loadStudents, loadProfile,
    saveAssignment, updateAssignment,
    saveSubmission, deleteSubmission,
    upsertProfile, saveStudent,
    loadRequests, saveRequest, updateRequest,
    loadAvailability, saveAvailability, deleteAvailability,
    loadSessions, saveSession,
    uploadAvatar, uploadSubmissionPhoto,
  };
}

