        {[{l:"Toplam",v:myA.length},{l:"Tamamlandı",v:done},{l:"Bekleyen",v:pend.length},{l:"Rozet",v:done>=3?"🥇":done>=2?"🥈":done>=1?"🥉":"—"}].map((s,i)=><div key={i} className="stat-card"><div className="stat-label">{s.l}</div><div className="stat-value">{s.v}</div></div>)}
