// Ne değişti verileri (farklı emoji çiftleri)
// FarkBulOyunu — PAIRS'tan dinamik üretilir, her tur farklı
function buildFarkRound() {
  const allPairs = Object.values(PAIRS).flat();
  // 6 farklı kelime seç
  const shuffled = [...allPairs].map(p=>({...p,_r:Math.random()})).sort((a,b)=>a._r-b._r).slice(0,6);
  const farkliIdx = Math.floor(Math.random()*6);
  // Farklı kelime için başka bir çift bul
  const alternatif = allPairs.filter(p=>p.k !== shuffled[farkliIdx].k)
    .map(p=>({...p,_r:Math.random()})).sort((a,b)=>a._r-b._r)[0];
  const a = shuffled.map(p=>({w:p.w, k:p.k, img:getImgForWord(p.w,p.k)}));
  const b = shuffled.map((p,i)=> i===farkliIdx
    ? {w:alternatif.w, k:alternatif.k, img:getImgForWord(alternatif.w,alternatif.k)}
    : {w:p.w, k:p.k, img:getImgForWord(p.w,p.k)}
  );
  return { a, b, farkli: farkliIdx };
}

// İlk harf bulma (emoji → hangisi bu harfle başlar?)
// İlk ses bulma — PAIRS'tan otomatik üretilir, tüm harfler desteklenir
// Her tur: seçilen harften 1 doğru + diğer harflerden 3 yanlış emoji
function getIlkSesRound(letter) {
  const dogruHavuz = PAIRS[letter] || PAIRS["K"];
  const dogru = dogruHavuz[Math.floor(Math.random()*dogruHavuz.length)];
  const yanlisPairs = Object.entries(PAIRS)
    .filter(([l])=>l!==letter)
    .flatMap(([,arr])=>arr)
    .sort(()=>Math.random()-.5)
    .slice(0,3);
  const secenekler = [dogru,...yanlisPairs]
    .sort(()=>Math.random()-.5)
    .map(p=>({...p, img: getImgForWord(p.w, p.k)}));
  return { dogru:{...dogru, img:getImgForWord(dogru.w, dogru.k)}, secenekler };
}

